<script setup>
import {computed,shallowRef} from 'vue'
import {markets,hotStocks,fmt,path} from '../data'
import Coin from './Coin.vue'
const props=defineProps({all:Boolean})
const category=shallowRef("aiQuant.templates.filterAll"),query=shallowRef('')
const visible=computed(()=>markets.filter(m=>(category.value==="aiQuant.templates.filterAll"||m.category===category.value)&&m.name.toLowerCase().includes(query.value.toLowerCase())).slice(0,props.all?100:8))
</script>
<template><section id="markets" class="market-section"><div class="container"><h2 class="section-heading">{{ $t("home.markets.title") }}<em>{{ $t("home.markets.titleHighlight") }}</em></h2><p class="eyebrow">{{ $t("home.markets.pulseLabel") }}</p><div class="hot-grid"><div v-for="s in hotStocks" :key="s[0]" class="stock-card"><span>{{ $t(s[0]) }}</span><strong :class="s[3].startsWith('-')?'negative':'positive'">{{ $t(s[1]) }}</strong><div :class="s[3].startsWith('-')?'negative':'positive'"><span>{{ $t(s[2]) }}</span><span>{{ $t(s[3]) }}</span></div></div></div><div class="market-filters"><div class="tabs"><button v-for="c in [&quot;aiQuant.templates.filterAll&quot;,&quot;home.products.perpTag1&quot;,&quot;aiQuant.market.forex&quot;,&quot;aiQuant.market.stock&quot;]" :key="c" :aria-pressed="category===c" :class="{active:category===c}" @click="category=c">{{ $t(c) }}</button></div><input v-if="all" v-model="query" :placeholder="$t(&quot;trade.searchSymbol&quot;)" :aria-label="$t(&quot;trade.searchSymbol&quot;)"/></div><div class="market-table"><table><thead><tr><th>{{ $t("aiQuant.templates.fields.supportedSymbols") }}</th><th>{{ $t("home.markets.colPrice") }}</th><th class="market-extra">{{ $t("home.markets.colChange") }}</th><th class="market-extra">{{ $t("home.markets.colVolume") }}</th><th><span class="sr-only">{{ $t("aiQuant.table.columns.action") }}</span></th></tr></thead><tbody><tr v-for="m in visible" :key="m.id"><td><div class="coin-label"><Coin :symbol="m.symbol"/>{{ $t(m.name) }}</div><small class="mobile-market-details" :class="m.change<0?'negative':'positive'">{{ $t(m.change>0?'+':'') }}{{ $t(m.change.toFixed(2)) }}% · {{ $compact(m.volume) }}</small></td><td>{{ $t(fmt(m.price)) }}</td><td class="market-extra" :class="m.change<0?'negative':'positive'">{{ $t(m.change>0?'+':'') }}{{ $t(m.change.toFixed(2)) }}%</td><td class="market-extra muted">{{ $compact(m.volume) }}</td><td><RouterLink :to="path('/trade/futures/'+m.id)" :aria-label="$t('common.tradeMarket',{symbol:m.name})">{{ $t("home.markets.tradeLink") }}</RouterLink></td></tr></tbody></table><p v-if="!visible.length" class="empty">{{ $t("markets.ui.noMatchingMarkets") }}</p><RouterLink class="market-more" :to="path('/trade/futures/BTCUSD')">{{ $t("home.markets.viewAllPlain") }}</RouterLink></div></div></section></template>
